/* ═══════════ Progression & costs ═══════════
 * 1.56 — nouvelle D.A : rail néon par catégorie (une couleur chacune), bandeau de page avec résumé vivant, panneaux séparés,
 * modes en grosses tuiles, cartes de courbes + graphique comparatif (XP et stats payantes), simulateur, boutons − / + sur les nombres. */
const MODE_IC = { curve: "fa-chart-area", tiers: "fa-stairs", multiplier: "fa-chart-line", manual: "fa-list-ol", simple: "fa-plus-minus", formula: "fa-square-root-variable" };
