  const lg = all.flatMap(x => x[2].map(y => Math.log10(y))); const mn = Math.min(...lg) - 0.05, mx = Math.max(...lg);
  const grid = [0, .25, .5, .75, 1].map(t => { const y = (H - 3 - t * (H - 6)).toFixed(1); return `<line x1="0" x2="${W}" y1="${y}" y2="${y}" class="gl"/><text x="4" y="${Math.max(10, y - 3)}">${short(10 ** (mn + t * (mx - mn)))}</text>`; }).join("");
